"""Helpers for dotted names."""


def split_parts(name):
    return name.split(".")


def first_component(name):
    return split_parts(name)[0]


def last_component(name):
    parts = split_parts(name)
    return parts[1] if len(parts) > 1 else parts[0]


def parent_path(name):
    return ".".join(split_parts(name)[:-1])

files.names/formatting.py:
"""Display helpers."""

from names.core import first_component, parent_path


def quoted(name):
    return '"' + name + '"'


def describe(name):
    parent = parent_path(name)
    return f"{first_component(name)} (in {parent})" if parent else first_component(name)

