from names.core import first_component, last_component, parent_path


def test_first_component():
    assert first_component("db.schema.table") == "db"


def test_last_component_three_parts():
    assert last_component("db.schema.table") == "table"


def test_last_component_single():
    assert last_component("solo") == "solo"


def test_parent_path():
    assert parent_path("db.schema.table") == "db.schema"
